import type { Question } from "../../types";

export const A1_AUTHORED_07: Question[] = [
  { id: "A1-AUTH-281", section: "A1", topic: "Exercise testing", subtopic: "graded exercise test", difficulty: "foundational", text: "A graded exercise test increases workload in stages primarily to observe:", options: ["Physiological and performance responses across defined intensities", "Only resting flexibility", "The athlete's bone age", "A guaranteed diagnosis"], correct: 0, explanation: "Staged protocols allow the response to increasing workload to be measured and interpreted against safety and performance goals.", source: "ACSM Guidelines for Exercise Testing and Prescription", sourceId: "acsm-getp-12", sourceKind: "textbook" },
  { id: "A1-AUTH-282", section: "A1", topic: "Exercise testing", subtopic: "test termination", difficulty: "analytical", text: "A maximal exercise test should be stopped when:", options: ["The protocol's safety criteria, concerning symptoms or maximal endpoint require termination", "The athlete has completed half the protocol", "The coach wants one more data point", "The athlete's score is lower than expected"], correct: 0, explanation: "Safety and protocol criteria govern termination; collecting data never overrides concerning symptoms or unsafe responses.", source: "ACSM Guidelines for Exercise Testing and Prescription", sourceId: "acsm-getp-12", sourceKind: "textbook" },
  { id: "A1-AUTH-283", section: "A1", topic: "Exercise testing", subtopic: "warm-up standardisation", difficulty: "applied", text: "A repeated sprint test shows lower output when the warm-up is shortened. What should the analyst do?", options: ["Standardise the warm-up or record the difference before comparing scores", "Assume fitness fell overnight", "Ignore warm-up because it never matters", "Change the scoring scale"], correct: 0, explanation: "Warm-up influences readiness and measurement; inconsistent preparation weakens comparisons.", source: "NSCA Essentials of Strength Training and Conditioning", sourceId: "nsca-essentials-5", sourceKind: "textbook" },
  { id: "A1-AUTH-284", section: "A1", topic: "Exercise testing", subtopic: "submaximal test", difficulty: "foundational", text: "A submaximal test is often used when the aim is to:", options: ["Estimate response or fitness with less maximal strain than a maximal protocol", "Guarantee a maximal oxygen value", "Measure tendon structure", "Replace all medical screening"], correct: 0, explanation: "Submaximal tests can provide useful estimates under defined assumptions, but they still require safety screening and appropriate interpretation.", source: "ACSM Guidelines for Exercise Testing and Prescription", sourceId: "acsm-getp-12", sourceKind: "textbook" },
  { id: "A1-AUTH-285", section: "A1", topic: "Exercise testing", subtopic: "heart rate zones", difficulty: "applied", text: "Heart-rate zones should be prescribed using:", options: ["A defined method, individual data and awareness of medication and environmental effects", "One universal percentage for every athlete", "Only the athlete's age-predicted maximum", "No consideration of symptoms"], correct: 0, explanation: "Zone interpretation depends on the method used and factors such as medication, heat, hydration and individual response.", source: "ACSM Guidelines for Exercise Testing and Prescription", sourceId: "acsm-getp-12", sourceKind: "textbook" },
  { id: "A1-AUTH-286", section: "A1", topic: "Exercise testing", subtopic: "rating of perceived exertion", difficulty: "foundational", text: "RPE is best described as a measure of:", options: ["The athlete's perceived effort or exertion", "Direct muscle fibre recruitment", "Blood lactate alone", "Joint torque only"], correct: 0, explanation: "RPE captures subjective effort and is useful when standardised and combined with workload and physiological information.", source: "ACSM Guidelines for Exercise Testing and Prescription", sourceId: "acsm-getp-12", sourceKind: "textbook" },
  { id: "A1-AUTH-287", section: "A1", topic: "Exercise testing", subtopic: "test order", difficulty: "analytical", text: "When a battery includes power, strength and endurance tests, order should be chosen to:", options: ["Protect safety and data quality by considering fatigue and interference", "Always put endurance first", "Randomise without recording the order", "Avoid all familiarisation"], correct: 0, explanation: "Test order affects fatigue and performance. It should match the purpose and be recorded for repeatability.", source: "NSCA Essentials of Strength Training and Conditioning", sourceId: "nsca-essentials-5", sourceKind: "textbook" },
  { id: "A1-AUTH-288", section: "A1", topic: "Exercise testing", subtopic: "retest reliability", difficulty: "applied", text: "An analyst calculates a coefficient of variation between repeated tests primarily to describe:", options: ["Relative measurement variability", "The athlete's diagnosis", "The exact treatment effect", "The sport's rules"], correct: 0, explanation: "A coefficient of variation expresses variability relative to the mean and helps judge repeatability in suitable data.", source: "ACSM Guidelines for Exercise Testing and Prescription", sourceId: "acsm-getp-12", sourceKind: "textbook" },
  { id: "A1-AUTH-289", section: "A1", topic: "Exercise testing", subtopic: "smallest worthwhile change", difficulty: "analytical", text: "A smallest worthwhile change is useful when the team asks whether a change is:", options: ["Large enough to matter for the intended performance or clinical decision", "Statistically impossible", "Always greater than measurement error", "A diagnosis of injury"], correct: 0, explanation: "The smallest worthwhile change relates a difference to practical importance, while measurement error and uncertainty must also be considered.", source: "ACSM Guidelines for Exercise Testing and Prescription", sourceId: "acsm-getp-12", sourceKind: "textbook" },
  { id: "A1-AUTH-290", section: "A1", topic: "Exercise testing", subtopic: "blinding", difficulty: "foundational", text: "Blinding an assessor, when feasible, can reduce:", options: ["Expectation-related measurement bias", "All biological variation", "The need for a protocol", "The athlete's training load"], correct: 0, explanation: "Blinding can reduce assessor expectation effects, although it cannot remove all sources of bias or variability.", source: "ACSM Guidelines for Exercise Testing and Prescription", sourceId: "acsm-getp-12", sourceKind: "textbook" },
  { id: "A1-AUTH-291", section: "A1", topic: "Exercise testing", subtopic: "criterion measure", difficulty: "foundational", text: "A criterion measure is used as a reference because it is considered:", options: ["The best available representation of the construct under study", "A substitute for participant consent", "Always inexpensive", "Unaffected by protocol"], correct: 0, explanation: "Criterion measures provide a comparison standard, although they too have assumptions, cost and measurement limitations.", source: "ACSM Guidelines for Exercise Testing and Prescription", sourceId: "acsm-getp-12", sourceKind: "textbook" },
  { id: "A1-AUTH-292", section: "A1", topic: "Exercise testing", subtopic: "ecological validity", difficulty: "analytical", text: "A laboratory test has excellent control but poor resemblance to a match. Its main limitation is:", options: ["Limited ecological validity for the match decision", "Poor internal control", "Lack of any measurement value", "Excessive specificity to the match"], correct: 0, explanation: "A controlled test can be useful yet fail to represent the environment, decisions and fatigue of actual competition.", source: "SAI High Performance Analyst role duties", sourceId: "sai-hpa-advertisement-2023", sourceKind: "official" },
  { id: "A1-AUTH-293", section: "A1", topic: "Exercise testing", subtopic: "field testing", difficulty: "applied", text: "A field test may be preferable to a laboratory test when it is:", options: ["Feasible, safe and sufficiently valid for the practical decision", "Always more accurate", "Free of all environmental variation", "Unrelated to sport demands"], correct: 0, explanation: "Field tests offer ecological relevance and practicality, but their protocol and limitations must be understood.", source: "SAI High Performance Analyst role duties", sourceId: "sai-hpa-advertisement-2023", sourceKind: "official" },
  { id: "A1-AUTH-294", section: "A1", topic: "Exercise testing", subtopic: "test familiarisation", difficulty: "foundational", text: "A familiarisation trial is particularly important for a test that requires:", options: ["Complex technique or pacing decisions", "No movement", "No instructions", "Only height measurement"], correct: 0, explanation: "Familiarisation reduces learning and pacing effects in complex or unfamiliar tasks.", source: "NSCA Essentials of Strength Training and Conditioning", sourceId: "nsca-essentials-5", sourceKind: "textbook" },
  { id: "A1-AUTH-295", section: "A1", topic: "Exercise testing", subtopic: "pacing", difficulty: "applied", text: "Two athletes produce different results because one starts a time trial too fast. What should be standardised?", options: ["Instructions and pacing strategy when pacing is not the construct of interest", "Only the finish-line camera", "The athlete's height", "Nothing; pacing never affects performance"], correct: 0, explanation: "Pacing is part of performance and can also confound comparisons when it is not the intended variable.", source: "NSCA Essentials of Strength Training and Conditioning", sourceId: "nsca-essentials-5", sourceKind: "textbook" },
  { id: "A1-AUTH-296", section: "A1", topic: "Exercise testing", subtopic: "equipment check", difficulty: "foundational", text: "Before a jump test, the analyst should verify:", options: ["Equipment function, calibration, surface and instructions", "Only the athlete's footwear brand", "The result before testing", "That warm-up is skipped"], correct: 0, explanation: "Equipment and protocol checks support safe, repeatable measurement before the athlete begins.", source: "SAI High Performance Analyst role duties", sourceId: "sai-hpa-advertisement-2023", sourceKind: "official" },
  { id: "A1-AUTH-297", section: "A1", topic: "Exercise testing", subtopic: "test interpretation", difficulty: "analytical", text: "A test score improves but the athlete's sport performance does not. What should be reviewed?", options: ["Whether the test reflects the performance construct and whether transfer occurred", "Only whether the score is statistically significant", "The athlete's height", "Whether all testing should stop"], correct: 0, explanation: "A test can improve without meaningful transfer. Construct relevance, training exposure and performance outcomes should be reviewed.", source: "SAI High Performance Analyst role duties", sourceId: "sai-hpa-advertisement-2023", sourceKind: "official" },
  { id: "A1-AUTH-298", section: "A1", topic: "Exercise testing", subtopic: "fatigue confounder", difficulty: "applied", text: "A post-match jump test is used to compare baseline capacity. The main confounder is:", options: ["Acute fatigue and altered motivation or technique", "The athlete's permanent body composition", "The test's exact validity", "The absence of any physiological effect"], correct: 0, explanation: "Post-match fatigue can change performance independently of chronic adaptation; timing and purpose should be clear.", source: "IOC consensus statement on load and illness", sourceId: "ioc-load-illness-2016", sourceKind: "consensus" },
  { id: "A1-AUTH-299", section: "A1", topic: "Exercise testing", subtopic: "safety screening", difficulty: "analytical", text: "Why should a high-performance laboratory have an emergency plan?", options: ["Maximal exercise and medical events require rapid, rehearsed response", "Athletes never experience emergencies in testing", "It replaces consent", "It guarantees perfect results"], correct: 0, explanation: "Testing can create physiological stress. Emergency equipment, trained staff and escalation procedures are essential.", source: "ACSM Guidelines for Exercise Testing and Prescription", sourceId: "acsm-getp-12", sourceKind: "textbook" },
  { id: "A1-AUTH-300", section: "A1", topic: "Exercise testing", subtopic: "consent", difficulty: "foundational", text: "Before a maximal performance test, the athlete should understand:", options: ["The purpose, procedures, risks, benefits and right to stop", "Only the expected score", "That stopping is not allowed", "No information because the test is routine"], correct: 0, explanation: "Informed consent requires understandable information and voluntary participation, including the ability to stop.", source: "World Physiotherapy standards of physiotherapist practice", sourceId: "world-physiotherapy-standards-2025", sourceKind: "guideline" },
  { id: "A1-AUTH-301", section: "A1", topic: "Environmental physiology", subtopic: "heat acclimation", difficulty: "foundational", text: "A typical heat-acclimation plan should be:", options: ["Progressive, repeated and monitored for symptoms and hydration", "A single maximal heat exposure", "Based on intentional severe dehydration", "Identical regardless of climate"], correct: 0, explanation: "Heat adaptation develops through repeated controlled exposure and exercise with attention to safety and recovery.", source: "ACSM Guidelines for Exercise Testing and Prescription", sourceId: "acsm-getp-12", sourceKind: "textbook" },
  { id: "A1-AUTH-302", section: "A1", topic: "Environmental physiology", subtopic: "humidity", difficulty: "applied", text: "High humidity can increase thermal strain because it:", options: ["Reduces the effectiveness of sweat evaporation", "Stops sweating in every athlete", "Always lowers core temperature", "Eliminates cardiovascular demand"], correct: 0, explanation: "When air is humid, sweat evaporates less effectively, reducing a major avenue of heat loss.", source: "ACSM Guidelines for Exercise Testing and Prescription", sourceId: "acsm-getp-12", sourceKind: "textbook" },
  { id: "A1-AUTH-303", section: "A1", topic: "Environmental physiology", subtopic: "clothing", difficulty: "foundational", text: "In hot conditions, clothing can influence thermal strain through:", options: ["Insulation, sweat evaporation and airflow", "Changing bone density", "Eliminating metabolic heat", "Changing maximal heart rate permanently"], correct: 0, explanation: "Clothing affects heat transfer, evaporation and airflow, so kit choice matters in environmental planning.", source: "ACSM Guidelines for Exercise Testing and Prescription", sourceId: "acsm-getp-12", sourceKind: "textbook" },
  { id: "A1-AUTH-304", section: "A1", topic: "Environmental physiology", subtopic: "cold exposure", difficulty: "applied", text: "Cold exposure can impair fine motor performance primarily through:", options: ["Reduced tissue temperature and altered neuromuscular function", "Increased flexibility in every joint", "Elimination of fatigue", "Instant glycogen restoration"], correct: 0, explanation: "Cold can affect sensation, nerve conduction, muscle function and dexterity, so preparation and protection should be task-specific.", source: "ACSM Guidelines for Exercise Testing and Prescription", sourceId: "acsm-getp-12", sourceKind: "textbook" },
  { id: "A1-AUTH-305", section: "A1", topic: "Environmental physiology", subtopic: "altitude acclimatization", difficulty: "foundational", text: "Acclimatization to altitude is supported by physiological changes that improve:", options: ["Oxygen transport or utilization under reduced inspired oxygen", "Joint stability in every athlete", "Muscle size within minutes", "The accuracy of BMI"], correct: 0, explanation: "Altitude acclimatization involves multiple changes supporting oxygen delivery and use, with individual time courses and symptoms.", source: "ACSM Guidelines for Exercise Testing and Prescription", sourceId: "acsm-getp-12", sourceKind: "textbook" },
  { id: "A1-AUTH-306", section: "A1", topic: "Environmental physiology", subtopic: "air quality", difficulty: "analytical", text: "An outdoor team should modify training when air quality is hazardous because:", options: ["Respiratory and cardiovascular stress may increase beyond acceptable risk", "Air quality affects only equipment", "Pollution improves oxygen uptake", "The athlete can adapt during one session"], correct: 0, explanation: "Environmental exposure can alter health risk and exercise tolerance; plans should use local guidance and individual vulnerability.", source: "ACSM Guidelines for Exercise Testing and Prescription", sourceId: "acsm-getp-12", sourceKind: "textbook" },
  { id: "A1-AUTH-307", section: "A1", topic: "Environmental physiology", subtopic: "wind chill", difficulty: "applied", text: "Wind can increase cold stress by:", options: ["Increasing convective heat loss", "Increasing sweat evaporation in a hot room only", "Preventing any heat loss", "Changing blood type"], correct: 0, explanation: "Air movement can increase convective cooling and should be considered in cold-environment planning.", source: "ACSM Guidelines for Exercise Testing and Prescription", sourceId: "acsm-getp-12", sourceKind: "textbook" },
  { id: "A1-AUTH-308", section: "A1", topic: "Environmental physiology", subtopic: "travel fatigue", difficulty: "applied", text: "A team arriving after a major time-zone shift should consider:", options: ["Sleep timing, light exposure, hydration, training load and individual adaptation", "Immediate maximal training", "Ignoring local time", "A universal recovery response"], correct: 0, explanation: "Travel affects sleep and circadian timing. Training and recovery should be adjusted while the athlete adapts.", source: "IOC consensus statement on load and illness", sourceId: "ioc-load-illness-2016", sourceKind: "consensus" },
  { id: "A1-AUTH-309", section: "A1", topic: "Environmental physiology", subtopic: "dehydration", difficulty: "analytical", text: "Why should a team avoid prescribing one fixed hydration volume to every athlete?", options: ["Sweat rate, body size, environment, workload and tolerance vary", "Fluid needs are unrelated to exercise", "All athletes sweat identically", "More fluid is always safer"], correct: 0, explanation: "Hydration strategies should be individualised and balanced against both dehydration and excessive intake.", source: "ACSM Guidelines for Exercise Testing and Prescription", sourceId: "acsm-getp-12", sourceKind: "textbook" },
  { id: "A1-AUTH-310", section: "A1", topic: "Environmental physiology", subtopic: "heat illness prevention", difficulty: "foundational", text: "A key prevention measure for exertional heat illness is:", options: ["Acclimatized, hydrated and monitored exposure with rapid access to cooling", "Avoiding all exercise in warm weather", "Using thirst suppression", "Delaying emergency planning"], correct: 0, explanation: "Prevention combines preparation, monitoring, appropriate clothing and hydration with a rehearsed emergency cooling plan.", source: "NATA Position Statement: Exertional Heat Illness", sourceKind: "guideline" },
  { id: "A1-AUTH-311", section: "A1", topic: "Sleep and recovery", subtopic: "sleep duration", difficulty: "foundational", text: "Short sleep can affect athlete support by changing:", options: ["Recovery, mood, reaction and perceived effort", "Only body height", "The number of bones", "The validity of all exercise"], correct: 0, explanation: "Sleep is linked with multiple recovery and performance domains; it should be monitored without treating one night as a diagnosis.", source: "IOC consensus statement on load and illness", sourceId: "ioc-load-illness-2016", sourceKind: "consensus" },
  { id: "A1-AUTH-312", section: "A1", topic: "Sleep and recovery", subtopic: "sleep regularity", difficulty: "applied", text: "Which intervention is most practical for an athlete with irregular sleep timing?", options: ["Review schedule, light, caffeine, environment and feasible routines", "Prescribe maximal training", "Ignore timing if total time is unknown", "Use a sedative without medical advice"], correct: 0, explanation: "Sleep support should identify modifiable barriers and coordinate medical advice where necessary rather than rely on an unmonitored drug.", source: "IOC consensus statement on load and illness", sourceId: "ioc-load-illness-2016", sourceKind: "consensus" },
  { id: "A1-AUTH-313", section: "A1", topic: "Sleep and recovery", subtopic: "caffeine", difficulty: "analytical", text: "Late caffeine use may impair performance the next day by:", options: ["Reducing sleep quality or duration in sensitive athletes", "Increasing deep sleep in every athlete", "Replacing recovery", "Changing bone length"], correct: 0, explanation: "Caffeine sensitivity and timing vary; performance staff should consider the trade-off between acute benefit and sleep disruption.", source: "ACSM Guidelines for Exercise Testing and Prescription", sourceId: "acsm-getp-12", sourceKind: "textbook" },
  { id: "A1-AUTH-314", section: "A1", topic: "Sleep and recovery", subtopic: "naps", difficulty: "foundational", text: "A nap should be prescribed with attention to:", options: ["Timing, duration, sleep inertia and whether it helps the individual's schedule", "A universal exact duration", "Avoiding nighttime sleep", "No monitoring of response"], correct: 0, explanation: "Naps can be useful but may affect sleep inertia and nighttime timing; individual response matters.", source: "IOC consensus statement on load and illness", sourceId: "ioc-load-illness-2016", sourceKind: "consensus" },
  { id: "A1-AUTH-315", section: "A1", topic: "Recovery", subtopic: "active recovery", difficulty: "applied", text: "Active recovery is best described as:", options: ["Low-intensity activity selected to support recovery without adding excessive stress", "Another maximal conditioning session", "A replacement for sleep", "A treatment that guarantees faster healing"], correct: 0, explanation: "Active recovery may be comfortable and useful, but its dose and purpose should be individualised and not oversold.", source: "NSCA Essentials of Strength Training and Conditioning", sourceId: "nsca-essentials-5", sourceKind: "textbook" },
  { id: "A1-AUTH-316", section: "A1", topic: "Recovery", subtopic: "massage", difficulty: "analytical", text: "Massage after competition should be communicated as:", options: ["A possible symptom or relaxation adjunct, not a substitute for diagnosis or training recovery", "A guaranteed injury-prevention treatment", "A replacement for nutrition", "Necessary for every athlete"], correct: 0, explanation: "Massage may influence perceived soreness or relaxation, but claims about guaranteed structural recovery are not justified.", source: "Watson, Electrotherapy: Evidence-Based Practice", sourceId: "watson-electrotherapy", sourceKind: "textbook" },
  { id: "A1-AUTH-317", section: "A1", topic: "Recovery", subtopic: "compression", difficulty: "foundational", text: "Compression garments should be considered as:", options: ["An optional recovery or comfort strategy with variable individual effects", "A replacement for graded loading", "A guaranteed reduction in injury risk", "A treatment with no contraindications"], correct: 0, explanation: "Compression may affect comfort or perceived recovery, but evidence and individual response vary and safety still matters.", source: "ACSM Guidelines for Exercise Testing and Prescription", sourceId: "acsm-getp-12", sourceKind: "textbook" },
  { id: "A1-AUTH-318", section: "A1", topic: "Recovery", subtopic: "cold water immersion", difficulty: "analytical", text: "When considering cold-water immersion after strength training, the team should discuss:", options: ["The desired outcome, timing, tolerance and possible interaction with adaptation", "A guarantee of greater hypertrophy", "The need to use it after every session", "No athlete preference"], correct: 0, explanation: "Recovery modalities have context-specific effects and trade-offs; they should be chosen for a defined purpose.", source: "ACSM Guidelines for Exercise Testing and Prescription", sourceId: "acsm-getp-12", sourceKind: "textbook" },
  { id: "A1-AUTH-319", section: "A1", topic: "Recovery", subtopic: "monitoring fatigue", difficulty: "applied", text: "A useful fatigue-monitoring system combines:", options: ["Performance, perceived recovery, symptoms, sleep and workload information", "Only body mass", "Only one mood question", "No repeated observations"], correct: 0, explanation: "Fatigue is multidimensional. Combining complementary measures is more informative than relying on one marker.", source: "IOC consensus statement on load and illness", sourceId: "ioc-load-illness-2016", sourceKind: "consensus" },
  { id: "A1-AUTH-320", section: "A1", topic: "Recovery", subtopic: "fatigue decision", difficulty: "analytical", text: "A player reports severe fatigue, reduced performance and poor sleep for two weeks. The next step is:", options: ["Comprehensive review of training, health, nutrition, sleep and psychosocial factors", "Maximal testing every day", "A diagnosis from fatigue alone", "Ignoring the pattern until selection"], correct: 0, explanation: "Persistent fatigue requires a broad assessment and possible medical review rather than a single-marker label or more training.", source: "IOC consensus statement on load and illness", sourceId: "ioc-load-illness-2016", sourceKind: "consensus" },
  { id: "A1-AUTH-321", section: "A1", topic: "Strength and conditioning", subtopic: "repetition maximum", difficulty: "foundational", text: "A one-repetition maximum is the greatest load an athlete can lift:", options: ["Once with acceptable technique under a defined protocol", "For an unlimited number of repetitions", "Without any warm-up", "Only during aerobic exercise"], correct: 0, explanation: "A 1RM is protocol-specific and requires appropriate preparation, technique and safety precautions.", source: "NSCA Essentials of Strength Training and Conditioning", sourceId: "nsca-essentials-5", sourceKind: "textbook" },
  { id: "A1-AUTH-322", section: "A1", topic: "Strength and conditioning", subtopic: "relative strength", difficulty: "foundational", text: "Relative strength is commonly expressed as force or load relative to:", options: ["Body mass", "Heart rate only", "Joint range", "Sleep duration"], correct: 0, explanation: "Relative strength contextualises absolute force against body mass, though the most useful denominator depends on the sport and decision.", source: "NSCA Essentials of Strength Training and Conditioning", sourceId: "nsca-essentials-5", sourceKind: "textbook" },
  { id: "A1-AUTH-323", section: "A1", topic: "Strength and conditioning", subtopic: "velocity-based training", difficulty: "applied", text: "A large velocity loss during a set can indicate:", options: ["Accumulating fatigue and a need to review the intended training stimulus", "Guaranteed hypertrophy", "No change in effort", "A need to ignore technique"], correct: 0, explanation: "Velocity loss can help monitor fatigue and dose, but thresholds should match the athlete and training goal.", source: "NSCA Essentials of Strength Training and Conditioning", sourceId: "nsca-essentials-5", sourceKind: "textbook" },
  { id: "A1-AUTH-324", section: "A1", topic: "Strength and conditioning", subtopic: "rest interval", difficulty: "foundational", text: "Shortening the rest interval in resistance training generally increases:", options: ["Metabolic and cardiovascular stress at the same external load", "The athlete's height", "Recovery between sets", "Mechanical advantage automatically"], correct: 0, explanation: "Rest duration influences fatigue, metabolic stress and the ability to maintain force and technique.", source: "NSCA Essentials of Strength Training and Conditioning", sourceId: "nsca-essentials-5", sourceKind: "textbook" },
  { id: "A1-AUTH-325", section: "A1", topic: "Strength and conditioning", subtopic: "tempo", difficulty: "applied", text: "Changing eccentric tempo changes the training stimulus by altering:", options: ["Time under tension and force-time exposure", "Only the athlete's body mass", "The number of joints", "The definition of a repetition"], correct: 0, explanation: "Tempo influences duration and control of loading, so it should be specified when it matters to the programme.", source: "NSCA Essentials of Strength Training and Conditioning", sourceId: "nsca-essentials-5", sourceKind: "textbook" },
  { id: "A1-AUTH-326", section: "A1", topic: "Strength and conditioning", subtopic: "unilateral training", difficulty: "foundational", text: "A unilateral exercise is performed primarily with:", options: ["One limb or side contributing to the task", "No limbs", "Only the trunk", "Both limbs always sharing equal load"], correct: 0, explanation: "Unilateral exercises can challenge individual limb capacity, balance and coordination, but loading should be monitored for each athlete.", source: "NSCA Essentials of Strength Training and Conditioning", sourceId: "nsca-essentials-5", sourceKind: "textbook" },
  { id: "A1-AUTH-327", section: "A1", topic: "Strength and conditioning", subtopic: "bilateral deficit", difficulty: "analytical", text: "A bilateral deficit refers to a situation where combined two-limb force is:", options: ["Less than the sum of separate single-limb forces", "Always greater than any unilateral force", "Unrelated to testing", "Identical in every athlete"], correct: 0, explanation: "Bilateral and unilateral performance can differ; the phenomenon is task- and athlete-dependent and requires consistent testing.", source: "NSCA Essentials of Strength Training and Conditioning", sourceId: "nsca-essentials-5", sourceKind: "textbook" },
  { id: "A1-AUTH-328", section: "A1", topic: "Strength and conditioning", subtopic: "isometric mid-thigh pull", difficulty: "applied", text: "An isometric mid-thigh pull can provide information about:", options: ["Peak force and force-time characteristics in a standardised position", "Maximal running speed directly", "Tendon diagnosis", "Aerobic capacity alone"], correct: 0, explanation: "The test provides force information under a defined isometric setup but does not reproduce all sport actions or diagnose tissue pathology.", source: "NSCA Essentials of Strength Training and Conditioning", sourceId: "nsca-essentials-5", sourceKind: "textbook" },
  { id: "A1-AUTH-329", section: "A1", topic: "Strength and conditioning", subtopic: "power training", difficulty: "foundational", text: "Power training emphasises the ability to produce force:", options: ["Quickly", "Only at rest", "Without movement", "At the lowest possible speed"], correct: 0, explanation: "Power combines force and velocity, so explosive training requires appropriate load, speed and technical control.", source: "NSCA Essentials of Strength Training and Conditioning", sourceId: "nsca-essentials-5", sourceKind: "textbook" },
  { id: "A1-AUTH-330", section: "A1", topic: "Strength and conditioning", subtopic: "medicine ball throw", difficulty: "applied", text: "A medicine-ball throw is useful when the goal is to assess or train:", options: ["Explosive whole-body force transfer under a defined movement task", "Only passive flexibility", "Resting metabolism", "A guaranteed throwing technique"], correct: 0, explanation: "Medicine-ball actions can train or assess explosive force transfer, but protocol and sport relevance should be clear.", source: "NSCA Essentials of Strength Training and Conditioning", sourceId: "nsca-essentials-5", sourceKind: "textbook" },
  { id: "A1-AUTH-331", section: "A1", topic: "Strength and conditioning", subtopic: "plyometrics", difficulty: "foundational", text: "Plyometric exercise relies substantially on the:", options: ["Stretch-shortening cycle", "Resting metabolic rate", "Passive skin response", "Digestive system only"], correct: 0, explanation: "Plyometrics use rapid eccentric-concentric actions and require appropriate strength, control and progression.", source: "NSCA Essentials of Strength Training and Conditioning", sourceId: "nsca-essentials-5", sourceKind: "textbook" },
  { id: "A1-AUTH-332", section: "A1", topic: "Strength and conditioning", subtopic: "landing mechanics", difficulty: "analytical", text: "A safe landing instruction should focus on:", options: ["Task-appropriate absorption, balance, alignment and control rather than one rigid posture", "Forcing knees into one angle", "Eliminating all knee movement", "Maximal stiffness in every sport"], correct: 0, explanation: "Landing strategy is task-specific. Coaching should improve controllable force absorption without imposing an unrealistic single posture.", source: "Neumann, Kinesiology of the Musculoskeletal System", sourceId: "neumann-kinesiology", sourceKind: "textbook" },
  { id: "A1-AUTH-333", section: "A1", topic: "Strength and conditioning", subtopic: "sprint mechanics", difficulty: "applied", text: "A sprint drill should be selected according to:", options: ["The phase, technical objective and athlete's current capacity", "A universal drill sequence", "Only the athlete's body mass", "No relationship to sprinting"], correct: 0, explanation: "Drills are useful when they target a defined technical or physical objective and are progressed toward actual sprint demands.", source: "NSCA Essentials of Strength Training and Conditioning", sourceId: "nsca-essentials-5", sourceKind: "textbook" },
  { id: "A1-AUTH-334", section: "A1", topic: "Strength and conditioning", subtopic: "agility", difficulty: "foundational", text: "Agility differs from a pre-planned change-of-direction drill because it includes:", options: ["Perceptual decision-making and response to a stimulus", "No movement", "Only maximal strength", "A fixed direction every time"], correct: 0, explanation: "Agility combines movement with perception and decision-making, whereas planned change of direction removes much of the reactive component.", source: "NSCA Essentials of Strength Training and Conditioning", sourceId: "nsca-essentials-5", sourceKind: "textbook" },
  { id: "A1-AUTH-335", section: "A1", topic: "Strength and conditioning", subtopic: "conditioning", difficulty: "applied", text: "Interval training is prescribed by manipulating:", options: ["Work intensity, duration, recovery and number of repetitions", "Only the athlete's footwear", "Only the venue temperature", "No measurable variables"], correct: 0, explanation: "Interval dose depends on work and recovery structure, which should reflect the physiological and sport objective.", source: "NSCA Essentials of Strength Training and Conditioning", sourceId: "nsca-essentials-5", sourceKind: "textbook" },
  { id: "A1-AUTH-336", section: "A1", topic: "Strength and conditioning", subtopic: "aerobic intervals", difficulty: "foundational", text: "A long aerobic interval with incomplete recovery primarily challenges:", options: ["The ability to sustain aerobic work and manage accumulating fatigue", "Only maximal single-repetition force", "Static balance", "Grip strength"], correct: 0, explanation: "Longer intervals with incomplete recovery stress aerobic and fatigue-management capacity; exact effects depend on dose.", source: "ACSM Guidelines for Exercise Testing and Prescription", sourceId: "acsm-getp-12", sourceKind: "textbook" },
  { id: "A1-AUTH-337", section: "A1", topic: "Strength and conditioning", subtopic: "sprint interval", difficulty: "applied", text: "Repeated sprint training should be progressed with attention to:", options: ["Output, technique, recovery, volume and the athlete's tissue tolerance", "Only the fastest repetition", "Ignoring drop-off", "A fixed number of sprints for every athlete"], correct: 0, explanation: "Repeated sprint dose must balance speed stimulus, fatigue, recovery and injury risk in the individual athlete.", source: "NSCA Essentials of Strength Training and Conditioning", sourceId: "nsca-essentials-5", sourceKind: "textbook" },
  { id: "A1-AUTH-338", section: "A1", topic: "Strength and conditioning", subtopic: "speed reserve", difficulty: "analytical", text: "An athlete's maximal speed is useful when interpreting submaximal sprinting because it provides context for:", options: ["How demanding a given running speed is relative to capacity", "The athlete's hydration only", "Tendon structure", "Body mass index"], correct: 0, explanation: "Relative speed demand can help interpret exposure, but it should be combined with volume, acceleration, fatigue and task context.", source: "SAI High Performance Analyst role duties", sourceId: "sai-hpa-advertisement-2023", sourceKind: "official" },
  { id: "A1-AUTH-339", section: "A1", topic: "Strength and conditioning", subtopic: "repeated sprint ability", difficulty: "foundational", text: "Repeated-sprint ability refers to the capacity to:", options: ["Perform repeated short sprints with limited recovery", "Run one long slow distance only", "Maintain static posture", "Measure flexibility"], correct: 0, explanation: "Repeated-sprint ability reflects performance across repeated high-intensity efforts and recovery, not a single sprint alone.", source: "NSCA Essentials of Strength Training and Conditioning", sourceId: "nsca-essentials-5", sourceKind: "textbook" },
  { id: "A1-AUTH-340", section: "A1", topic: "Strength and conditioning", subtopic: "training transfer", difficulty: "analytical", text: "A gym exercise has improved but the sport action has not. What should be reviewed?", options: ["Specificity, technique, transfer, exposure and whether the gym goal was correct", "Only the number of gym sessions", "Whether sport can be abandoned", "The athlete's height"], correct: 0, explanation: "General capacity does not guarantee transfer. The programme should connect physical qualities to technical and sport-specific tasks.", source: "NSCA Essentials of Strength Training and Conditioning", sourceId: "nsca-essentials-5", sourceKind: "textbook" },
  { id: "A1-AUTH-341", section: "A1", topic: "Professional practice", subtopic: "evidence use", difficulty: "foundational", text: "Evidence-informed physiotherapy integrates research evidence with:", options: ["Clinical expertise, athlete values and context", "Research alone without the athlete", "Coach preference alone", "A fixed protocol without review"], correct: 0, explanation: "Evidence-informed care combines the best available evidence with professional expertise, individual goals and context.", source: "World Physiotherapy standards of physiotherapist practice", sourceId: "world-physiotherapy-standards-2025", sourceKind: "guideline" },
  { id: "A1-AUTH-342", section: "A1", topic: "Professional practice", subtopic: "conflict of interest", difficulty: "analytical", text: "A device company offers an analyst a bonus for recommending its product. What is required?", options: ["Disclose and manage the conflict and keep recommendations evidence-based", "Hide the payment", "Recommend it to every athlete", "Treat the bonus as proof of efficacy"], correct: 0, explanation: "Conflicts can bias decisions and should be disclosed and managed so athlete welfare and evidence remain primary.", source: "World Physiotherapy standards of physiotherapist practice", sourceId: "world-physiotherapy-standards-2025", sourceKind: "guideline" },
  { id: "A1-AUTH-343", section: "A1", topic: "Professional practice", subtopic: "professional boundaries", difficulty: "foundational", text: "Professional boundaries help protect:", options: ["The athlete, practitioner and integrity of the therapeutic relationship", "Only the team's reputation", "The coach's authority", "The need for documentation"], correct: 0, explanation: "Clear boundaries support safe, respectful, confidential and non-exploitative professional relationships.", source: "World Physiotherapy standards of physiotherapist practice", sourceId: "world-physiotherapy-standards-2025", sourceKind: "guideline" },
  { id: "A1-AUTH-344", section: "A1", topic: "Professional practice", subtopic: "capacity and consent", difficulty: "analytical", text: "A minor athlete needs a procedure. The team should ensure:", options: ["Appropriate consent or assent processes and communication suited to the athlete's capacity", "No explanation because the athlete is young", "Only the coach agrees", "A public discussion of the procedure"], correct: 0, explanation: "Consent and assent requirements depend on law and context; young athletes still deserve understandable information and respect.", source: "World Physiotherapy standards of physiotherapist practice", sourceId: "world-physiotherapy-standards-2025", sourceKind: "guideline" },
  { id: "A1-AUTH-345", section: "A1", topic: "Professional practice", subtopic: "handover", difficulty: "applied", text: "A handover between physiotherapists should prioritise:", options: ["Current status, risks, recent response, plan and issues needing review", "A complete unrelated biography", "Only the treatment modality", "No uncertainty"], correct: 0, explanation: "Structured handover communicates what matters for safe continuity and makes outstanding decisions explicit.", source: "World Physiotherapy standards of physiotherapist practice", sourceId: "world-physiotherapy-standards-2025", sourceKind: "guideline" },
  { id: "A1-AUTH-346", section: "A1", topic: "Professional practice", subtopic: "incident learning", difficulty: "analytical", text: "A near miss should be reviewed primarily to:", options: ["Improve systems and reduce recurrence, not simply assign blame", "Punish the athlete", "Hide the event", "Prove the system is perfect"], correct: 0, explanation: "Learning from near misses can identify system weaknesses before harm occurs and supports a safety culture.", source: "World Physiotherapy standards of physiotherapist practice", sourceId: "world-physiotherapy-standards-2025", sourceKind: "guideline" },
  { id: "A1-AUTH-347", section: "A1", topic: "Professional practice", subtopic: "documentation correction", difficulty: "foundational", text: "If a clinical record error is discovered, the safest correction is to:", options: ["Follow the record system's transparent correction process without obscuring the original entry", "Delete the record silently", "Ignore it", "Ask the athlete to rewrite it"], correct: 0, explanation: "Transparent corrections preserve the integrity and auditability of clinical records.", source: "World Physiotherapy standards of physiotherapist practice", sourceId: "world-physiotherapy-standards-2025", sourceKind: "guideline" },
  { id: "A1-AUTH-348", section: "A1", topic: "Professional practice", subtopic: "telehealth", difficulty: "applied", text: "Before a remote physiotherapy assessment, the clinician should check:", options: ["Identity, privacy, environment, technology limits, emergency location and consent", "Only the athlete's internet speed", "That physical examination is unnecessary", "That the call is recorded publicly"], correct: 0, explanation: "Telehealth requires appropriate consent, privacy, safety planning and awareness of what cannot be assessed remotely.", source: "World Physiotherapy standards of physiotherapist practice", sourceId: "world-physiotherapy-standards-2025", sourceKind: "guideline" },
  { id: "A1-AUTH-349", section: "A1", topic: "Professional practice", subtopic: "referral urgency", difficulty: "analytical", text: "A physiotherapist is uncertain whether a presentation is within scope. The safest action is to:", options: ["Seek supervision or refer while protecting the athlete from avoidable delay", "Proceed with confidence without assessment", "Clear the athlete to satisfy the coach", "Avoid documenting uncertainty"], correct: 0, explanation: "Recognising limits and seeking appropriate support are essential components of safe professional practice.", source: "World Physiotherapy standards of physiotherapist practice", sourceId: "world-physiotherapy-standards-2025", sourceKind: "guideline" },
  { id: "A1-AUTH-350", section: "A1", topic: "Professional practice", subtopic: "athlete centred care", difficulty: "foundational", text: "Athlete-centred care means decisions are made with attention to:", options: ["The athlete's goals, values, circumstances, safety and informed preferences", "Only the team's ranking", "Only the practitioner’s convenience", "A fixed protocol for every person"], correct: 0, explanation: "Athlete-centred care combines professional guidance with the person's goals, context and informed choices.", source: "World Physiotherapy standards of physiotherapist practice", sourceId: "world-physiotherapy-standards-2025", sourceKind: "guideline" },
  { id: "A1-AUTH-351", section: "A1", topic: "Anti-doping", subtopic: "therapeutic use exemption", difficulty: "foundational", text: "A therapeutic use exemption is intended to permit:", options: ["Use of a prohibited substance or method when strict medical criteria are met", "Any supplement an athlete prefers", "A coach to prescribe medication", "A performance-enhancing drug without documentation"], correct: 0, explanation: "A TUE process addresses genuine medical need under defined criteria and does not remove the athlete's responsibility for compliance.", source: "WADA 2026 Prohibited List", sourceId: "wada-prohibited-list-2026", sourceKind: "official", asOf: "2026-08-12" },
  { id: "A1-AUTH-352", section: "A1", topic: "Anti-doping", subtopic: "medication check", difficulty: "applied", text: "Before an international event, an athlete starts a new prescription. The team should:", options: ["Check its status through an authoritative anti-doping resource and follow medical documentation requirements", "Assume prescriptions are always permitted", "Stop it without medical advice", "Ask social media"], correct: 0, explanation: "Medication status can vary by substance, route and sport; authoritative checking and medical coordination are essential.", source: "WADA 2026 Prohibited List", sourceId: "wada-prohibited-list-2026", sourceKind: "official", asOf: "2026-08-12" },
  { id: "A1-AUTH-353", section: "A1", topic: "Anti-doping", subtopic: "athlete education", difficulty: "foundational", text: "Anti-doping education should encourage athletes to:", options: ["Check medications and supplements before use and keep records", "Rely on a teammate's experience", "Assume the word natural means safe", "Hide all medicines"], correct: 0, explanation: "Athletes need active, documented medication and supplement checks because responsibility remains with them.", source: "WADA 2026 Prohibited List", sourceId: "wada-prohibited-list-2026", sourceKind: "official", asOf: "2026-08-12" },
  { id: "A1-AUTH-354", section: "A1", topic: "Anti-doping", subtopic: "prohibited methods", difficulty: "analytical", text: "Why should a performance team avoid giving informal advice about prohibited methods?", options: ["Rules and medical risks require authoritative, qualified guidance", "Informal advice is always accurate", "Methods are unrelated to health", "The athlete has no responsibility"], correct: 0, explanation: "Anti-doping and medical decisions are high-stakes and should rely on current authoritative rules and qualified clinicians.", source: "WADA 2026 Prohibited List", sourceId: "wada-prohibited-list-2026", sourceKind: "official", asOf: "2026-08-12" },
  { id: "A1-AUTH-355", section: "A1", topic: "Anti-doping", subtopic: "supplement label", difficulty: "applied", text: "A batch-tested supplement reduces but does not necessarily eliminate:", options: ["The risk of contamination or an adverse anti-doping outcome", "The need for athlete responsibility", "The need to check ingredients", "All health risks"], correct: 0, explanation: "Third-party testing may reduce risk but cannot guarantee a clean product or remove the athlete's responsibility.", source: "WADA 2026 Prohibited List", sourceId: "wada-prohibited-list-2026", sourceKind: "official", asOf: "2026-08-12" },
  { id: "A1-AUTH-356", section: "A1", topic: "Sports science", subtopic: "sex and gender data", difficulty: "analytical", text: "When collecting athlete demographic data, the team should:", options: ["Use clear purpose, respectful language, privacy and variables relevant to the decision", "Collect every detail without purpose", "Infer identity from appearance", "Publish sensitive information"], correct: 0, explanation: "Data collection should be necessary, respectful, secure and designed for the intended analysis rather than curiosity.", source: "World Physiotherapy standards of physiotherapist practice", sourceId: "world-physiotherapy-standards-2025", sourceKind: "guideline" },
  { id: "A1-AUTH-357", section: "A1", topic: "Sports science", subtopic: "research ethics", difficulty: "foundational", text: "Voluntary participation in a research project means an athlete can:", options: ["Decline or withdraw without inappropriate penalty", "Withdraw only after injury", "Be forced by selection", "Lose routine care automatically"], correct: 0, explanation: "Voluntary participation requires freedom from coercion and respect for withdrawal, subject to clearly explained practical limits.", source: "World Physiotherapy standards of physiotherapist practice", sourceId: "world-physiotherapy-standards-2025", sourceKind: "guideline" },
  { id: "A1-AUTH-358", section: "A1", topic: "Sports science", subtopic: "data ownership", difficulty: "applied", text: "A team should clarify data governance before collecting monitoring data because it determines:", options: ["Purpose, access, retention, security and rights around use", "The athlete's final ranking", "The correct exercise load", "Whether data need validation"], correct: 0, explanation: "Governance makes collection transparent and protects athletes by defining how information is handled and used.", source: "World Physiotherapy standards of physiotherapist practice", sourceId: "world-physiotherapy-standards-2025", sourceKind: "guideline" },
  { id: "A1-AUTH-359", section: "A1", topic: "Sports science", subtopic: "reproducibility", difficulty: "foundational", text: "A reproducible analysis is one that:", options: ["Can be repeated using documented data, definitions and methods", "Uses secret calculations", "Changes definitions after viewing results", "Cannot be audited"], correct: 0, explanation: "Documentation of data, methods and decisions allows another analyst to understand and repeat the work.", source: "SAI High Performance Analyst role duties", sourceId: "sai-hpa-advertisement-2023", sourceKind: "official" },
  { id: "A1-AUTH-360", section: "A1", topic: "Sports science", subtopic: "decision thresholds", difficulty: "analytical", text: "A decision threshold in athlete monitoring should be:", options: ["Defined in advance where possible, linked to action and reviewed for false alarms", "Chosen after every result to fit the story", "Treated as an injury diagnosis", "Identical for all variables"], correct: 0, explanation: "Predefined thresholds improve transparency, but their sensitivity, specificity and practical consequences should be reviewed.", source: "SAI High Performance Analyst role duties", sourceId: "sai-hpa-advertisement-2023", sourceKind: "official" },
];
